mapper.select:
select id, user_id, game_type, challenge_date, region_id, start_at, clear_at, source, created_at, updated_at
from user_daily_challenge
where user_id = #{userId}
  and game_type = #{gameType, jdbcType=INTEGER, typeHandler=com.sniper.game.wordgame.typehandler.GameTypeEnumTypeHandler}
  and challenge_date = #{challengeDate}
limit 1
